-- State transitions declared for FileComment (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION bucket.file_comments_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'active'), ('active', 'deleted'), ('active', 'resolved'), ('resolved', 'active'), ('resolved', 'deleted'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: file_comments.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS file_comments_status_transition_check ON bucket.file_comments;
CREATE TRIGGER file_comments_status_transition_check
    BEFORE UPDATE OF "status" ON bucket.file_comments
    FOR EACH ROW EXECUTE FUNCTION bucket.file_comments_status_transition_check();
